// Signs a request to the LendLoop Convex HTTP API.
// Secrets come from the n8n container environment, never from this workflow file.
const crypto = require('crypto');
const secret = $env.N8N_TO_LENDLOOP_SECRET;
const base = $env.LENDLOOP_CONVEX_SITE_URL;
if (!secret || !base) throw new Error('N8N_TO_LENDLOOP_SECRET and LENDLOOP_CONVEX_SITE_URL must be set');
function signed(method, path, body = '') {
  const timestamp = Math.floor(Date.now() / 1000).toString();
  const signature = crypto.createHmac('sha256', secret).update(`${timestamp}.${method}.${path}.${body}`).digest('hex');
  return { url: base.replace(/\/$/, '') + path, timestamp, signature, body };
}

return [{ json: signed('GET', '/n8n/overdue-loans') }];

// Mock reminder channel: written to the n8n log. Replace with Email / Slack / Discord to go live.
// A failure for one borrower is recorded as "failed" for that loan instead of stopping the run.
const loan = $json;
try {
  if (!loan.borrower || !loan.borrower.email) throw new Error('borrower has no email address');
  const days = loan.daysOverdue === 1 ? '1 day' : `${loan.daysOverdue} days`;
  const text = `Hi ${loan.borrower.name}, the ${loan.toolName} you borrowed was due back on ${loan.endDate} (${days} ago). Please return it or message the owner in LendLoop.`;
  console.log(`[LendLoop reminder] to=${loan.borrower.email} key=${loan.reminderKey} :: ${text}`);
  // The write-back only carries IDs and status: the email address goes no further.
  return { json: { loanId: loan.loanId, reminderKey: loan.reminderKey, status: 'sent', channel: 'log' } };
} catch (e) {
  return { json: { loanId: loan.loanId, reminderKey: loan.reminderKey, status: 'failed', channel: 'log', error: String(e.message || e) } };
}

