// reminderKey = <loanId>:overdue:<date>, so retries and re-runs write the same record once.
const body = JSON.stringify({
  loanId: $json.loanId,
  reminderKey: $json.reminderKey,
  status: $json.status,
  channel: $json.channel,
  error: $json.error,
});
return { json: signed('POST', '/n8n/reminder-status', body) };
